import { RecipeAST, ImportDecl, SectionAST, ImportBinding, Meta, Location } from '@gram-lang/parser';
import { Warning, CompilationResult, ProcessedSection, WarningSeverity } from '@gram-lang/kitchen';
import { MassMetrics, AnalyzedCompilationResult, IngredientData } from '@gram-lang/analyzer';

/**
 * The one seam between this package and the outside world. This package
 * *defines* the interface but never implements it — resolving a specifier
 * to a URI and reading a URI's contents are both host-specific (the CLI
 * uses `node:path`/`node:fs`, the language server layers unsaved-editor
 * state over the filesystem, the playground has no filesystem at all, the
 * conformance runner resolves relative to a fixture directory) — see
 * `.notes/plan-ajout-imports-recettes.md` §B.2.
 */
interface ModuleHost {
    /** Resolves `specifier` against the URI of the importing document. Pure path arithmetic — must not touch the filesystem. */
    resolve(specifier: string, fromUri: string): string;
    /** Reads the source at `uri`. Throws (or rejects) when it can't — `loadModuleGraph` turns that into a `MODULE_NOT_FOUND` diagnostic, never a crash. */
    read(uri: string): string | Promise<string>;
}
interface ResolvedImport {
    decl: ImportDecl;
    uri: string;
}
interface ModuleRecord {
    uri: string;
    source: string;
    ast: RecipeAST;
    imports: ResolvedImport[];
}
interface ModuleGraph {
    entry: string;
    modules: Map<string, ModuleRecord>;
    order: string[];
    diagnostics: Warning[];
}

/**
 * An in-memory `ModuleHost`: a flat map of `uri` → source, POSIX-style
 * relative path resolution, no real filesystem. `uri`s are plain strings
 * like `"/recipe.gram"` or `"/bases/pate.gram"` — always absolute-looking so
 * `resolve` has an unambiguous "directory of the importer" to resolve
 * against, without needing an actual project root. `"@/..."` resolves
 * against this VFS's own root (`"/"`).
 *
 * Used by the unit tests in `tests/fake-host.ts` (re-exported from there
 * under its original name) and by the docs playground's multi-file editor,
 * which has no filesystem and no project-root concept at all.
 */
declare function createMemoryHost(files: Map<string, string> | Record<string, string>): ModuleHost;

interface ExportInfo {
    name: string;
    sectionIndex: number;
}
interface ModuleExports {
    sections: SectionAST[];
    exports: Map<string, ExportInfo>;
}
/**
 * Computes what a module exports (module-imports RFC, Phase A.4): only
 * section-level `->&` declarations are public — step-level intermediates
 * stay private, and so does anything a module merely *imports* itself
 * (deliberately not read from `ctx.globalScopes`, which would also capture
 * import bindings and leak transitive re-exports the module never opted
 * into).
 *
 * The "default" export is deterministic:
 * 1. the module's one and only section-level `->&`, if it has exactly one;
 * 2. otherwise, the *last* section, whether or not it declares its own
 *    `->&` — covering both "no sections were exported at all" and
 *    "multiple were, and none was singled out" the same way, since a
 *    module with several exports still needs *some* answer for
 *    `@use "..." as &name` (no destructuring).
 *
 * Every module contributes at least one section once grouped (§C.5): a
 * module that's just a bare sequence of steps, with no `## heading`
 * anywhere, becomes a single untitled section — never spilled loose into
 * the host's own untitled section.
 */
declare function computeExports(ast: RecipeAST): ModuleExports;

/**
 * Loads the full transitive import graph starting at `entryUri`. A single
 * depth-first pass: every URI is read and parsed at most once (a diamond —
 * A imports B and C, both import D — loads D once), cycles are detected via
 * the current DFS path rather than the whole visited set (so a diamond
 * isn't mistaken for a cycle), and `order` comes out leaves-first — the
 * order Phase D.1's yield-measurement pass needs, so a module's own
 * imports are always already measured by the time it is.
 *
 * Never throws on a bad module: a missing file, a syntax error, a cycle, or
 * an invalid specifier all become a diagnostic on the graph instead, so one
 * broken import doesn't take down the whole compose. Only `host.resolve`
 * throwing synchronously for a reason unrelated to the module system itself
 * would propagate — hosts are expected to make `resolve` pure path
 * arithmetic that doesn't throw.
 */
declare function loadModuleGraph(entryUri: string, host: ModuleHost, options?: {
    maxDepth?: number;
}): Promise<ModuleGraph>;

/**
 * Every intermediate name declared anywhere in a (already grouped) section
 * tree — both the section's own `->&` and any step-level one nested in its
 * steps. Used to find the "private and unbound-public" set that Phase C.2
 * needs to prefix: everything that isn't one of this import's own bound
 * names. Also reused by `compose.ts` to tell an unresolved `@use` binding
 * apart from a plain typo: a name declared here but absent from
 * `computeExports` exists in the module but was never re-exported.
 */
declare function collectIntermediateNames(sections: SectionAST[]): Set<string>;
/**
 * Builds the name → name rewrite table for one `@use` splice (Phase C.2):
 * a bound export (the module's own `->&x` matched by one of this import's
 * bindings) is renamed directly to the host's chosen local name; every
 * other intermediate — private (step-level) or public but not bound by
 * *this* import — is prefixed with the first binding's local name, joined
 * by `$` (a separator that never appears in a real ingredient/intermediate
 * name, since `slugify` collapses it away before it could ever collide with
 * one — see the post-slugify collision check in `checkRenameCollisions`,
 * the actual safety net).
 */
declare function buildRenameTable(sections: SectionAST[], exports: Map<string, ExportInfo>, bindings: ImportBinding[]): Map<string, string>;
declare function applyRename(sections: SectionAST[], table: Map<string, string>): SectionAST[];
/**
 * The post-rename safety net (Phase C.2): no separator survives
 * `slugify` (it collapses any run of non-alphanumerics to one hyphen), so
 * `pate$paton`, `pate·paton`, and `pate--paton` all produce the same id
 * `pate-paton` — choosing an "unlikely" separator protects nothing. This
 * checks the *slugified* result of every renamed name against a running set
 * of ids already claimed (by the host or by an earlier-spliced module) and
 * returns the names that collide, for the caller to turn into a
 * SCOPE_CONFLICT rather than silently merging two distinct intermediates.
 */
declare function checkRenameCollisions(renamedNames: Iterable<string>, claimedIds: Set<string>): string[];

interface ResolvedYield {
    value: number;
    unit: string;
    status: MassMetrics["massStatus"];
}
/**
 * Measures the yield of one export (§D.1): `masse(&x)`, recursively summing
 * that export's own section plus every section it references by name (see
 * `massOfSection`) — a flat `metrics.totalMass` read is only correct when
 * the export's section already covers the whole module's mass with no
 * reference chain leading outside it; the recursive form is a strict
 * superset, reducing to the same flat sum whenever that assumption holds,
 * and staying correct when it doesn't (a multi-section module where the
 * export's own section only *references* an earlier one).
 */
declare function resolveYield(analyzed: AnalyzedCompilationResult, exportInfo: ExportInfo): ResolvedYield;
interface ScaleFactorOptions {
    density?: number;
    lang?: string;
}
/**
 * The scale factor for one `@use` (§D.2): `max` over every bound export of
 * (sum of what the host explicitly requests of it) / (that export's
 * yield) — the same sum-within-an-export / max-across-exports pairing
 * Gram already uses for composite ingredients. A binding nobody put a
 * quantity on contributes nothing; if none of them did, the factor is 1.
 * Pushes MODULE_UNIT_MISMATCH / MODULE_BATCH_INTERPRETATION /
 * UNRESOLVED_MODULE_YIELD / ESTIMATED_MODULE_YIELD / MODULE_SURPLUS onto
 * `warnings` as it goes, each carrying `decl.loc` so it points at the
 * `@use` line responsible.
 */
declare function computeScaleFactor(hostChildren: RecipeAST["children"], decl: ImportDecl, moduleExports: Map<string, ExportInfo>, analyzed: AnalyzedCompilationResult, options: ScaleFactorOptions, warnings: Warning[]): number;

interface ModuleInfo {
    binding: string;
    uri: string;
    title: string | null;
    meta: Meta;
    scaleFactor: number;
    mode: "inline" | "stocked";
}
interface ComposedSection extends ProcessedSection {
    module?: Pick<ModuleInfo, "binding" | "uri" | "title" | "mode">;
}
interface ComposedCompilationResult extends CompilationResult {
    sections: ComposedSection[];
    modules?: ModuleInfo[];
}

interface ComposeOptions {
    db: Record<string, IngredientData>;
    lang?: string;
    cache?: Map<string, AnalyzedCompilationResult>;
    stock?: Set<string>;
}
interface ComposeResult {
    ast: RecipeAST;
    warnings: Warning[];
    modules: ModuleInfo[];
    sectionOrigins: (ModuleInfo | undefined)[];
    syntheticIngredients: Record<string, IngredientData>;
    usedStock: Set<string>;
}
/**
 * Composes a loaded `ModuleGraph` into a single flat `RecipeAST` (Phase C/D
 * of the module-imports RFC): every module is visited leaves-first, its own
 * imports spliced into copies of its own sections first (so a module that
 * itself imports something is already fully self-contained by the time
 * it's someone else's import target), measured (yield, mass) exactly once
 * per URI, and finally spliced into whoever imports it — scaled and
 * renamed *per import site*, since the same module can be imported more
 * than once (a diamond dependency) with different bindings and different
 * requested quantities each time.
 *
 * A `--stock`ed import ("stock" mechanism, module-imports RFC redesign)
 * splices nothing at all: zero timeline cost, one synthetic shopping-list
 * leaf sourced from the module's own real composition. A non-stocked import
 * carrying `@use`-level `~{...}` retro-planning gets that clause attached to
 * the section(s) that actually produce its bound export(s), letting ALAP's
 * normal backward chaining pull the whole sub-timeline along with it.
 */
declare function composeRecipe(graph: ModuleGraph, options: ComposeOptions): ComposeResult;
/**
 * Glue between `composeRecipe`'s output and `compile()`'s: attaches
 * `CompilationResult.modules` and tags each spliced section's
 * `ProcessedSection.module`, matched back to `compose.sectionOrigins` by
 * position — `compile()` preserves section order 1:1 from `ast.children`,
 * so index alignment is reliable even though the compiled shape carries no
 * location info of its own to correlate by.
 */
declare function finalizeComposed(compiled: CompilationResult, compose: Pick<ComposeResult, "modules" | "sectionOrigins" | "warnings">): ComposedCompilationResult;

/**
 * A reverse-dependency index: dep uri -> the set of uris that directly
 * `@use` it. Built from a flat edge list (importer -> dep) rather than from
 * a single `ModuleGraph`, since both consumers need edges collected across
 * *many* entry points, not one entry's transitive closure:
 *
 * - `gram watch` (module-imports RFC §F.0.3) needs to know, for every
 *   `.gram` file under the watched directory, who (transitively) imports it
 *   — not just what the changed file itself imports — so editing a base
 *   recipe re-checks every recipe that uses it, not only the file that
 *   changed on disk.
 * - The language server (RFC §G) needs the same thing to invalidate an open
 *   importer's diagnostics when an unsaved dependency changes.
 *
 * Kept host-agnostic here (no filesystem, no parsing) so it's written once
 * instead of twice — each caller collects its own edges (the CLI walks the
 * watched directory and parses every file's own `@use` lines; the language
 * server walks its open-document set) and hands them to
 * `buildReverseDependencyIndex`.
 */
type ReverseDependencyIndex = Map<string, Set<string>>;
interface DependencyEdge {
    /** The uri that declares the `@use`. */
    from: string;
    /** The uri it imports. */
    to: string;
}
declare function buildReverseDependencyIndex(edges: Iterable<DependencyEdge>): ReverseDependencyIndex;
/**
 * Every uri that transitively depends on `uri` — directly or through a
 * chain of imports — per `index`. Does not include `uri` itself. This is
 * the set that needs re-checking (or, for the language server, re-linting)
 * when `uri` changes.
 */
declare function transitiveDependents(index: ReverseDependencyIndex, uri: string): Set<string>;

